const row = $input.item.json;
const config = $('Config').first().json;

const transcriptRaw = row.transcript || '';
const truncated = transcriptRaw.length >= 49500;

let date = row.date;
if (!date || isNaN(Date.parse(date))) {
  date = new Date().toISOString().slice(0, 10);
} else {
  date = new Date(date).toISOString().slice(0, 10);
}

return {
  json: {
    recording_url: row.recording_url || '',
    title: row.title || 'Untitled Meeting',
    date,
    duration_seconds: Number(row.duration_seconds) || 0,
    transcript: transcriptRaw,
    summary: row.summary || '',
    action_items_raw: row.action_items || '',
    transcript_truncated: truncated,
    notionDataSourceId: config.notionDataSourceId,
    vaultInboxPath: config.vaultInboxPath
  }
};

const item = $input.item.json;

const transcriptSection = item.transcript_truncated
  ? `Transcript was truncated in the buffer sheet (50k character cell limit); use this summary and action items instead of the partial transcript.\nSummary: ${item.summary}\nAction items (raw): ${item.action_items_raw}`
  : `Full transcript:\n${item.transcript}`;

const systemPrompt = "You convert raw meeting transcripts into structured meeting notes. Respond with ONLY one valid JSON object - no markdown fences, no prose before or after, no explanation. Schema: tldr (string, 2-3 sentences), key_points (array of strings), decisions (array of strings, empty array if none), action_items (array of strings, empty array if none), open_questions (array of strings, empty array if none), suggested_client (one of: Nemours, AdventHealth, Paraveda, Sustena, CareMedx, ATAC, Encore, Internal - or null if genuinely unclear), suggested_meeting_type (one of: client, internal, 1-1, workshop), attendees (array of attendee names as strings, best effort from the transcript).";

const userPrompt = `Meeting title: ${item.title}\nDate: ${item.date}\nDuration (seconds): ${item.duration_seconds}\n\n${transcriptSection}`;

return {
  json: {
    ...item,
    anthropicRequestBody: {
      model: 'claude-sonnet-5',
      max_tokens: 2000,
      system: systemPrompt,
      messages: [ { role: 'user', content: userPrompt } ]
    }
  }
};

const item = $('Build Anthropic Request').item.json;
const claudeResponse = $input.item.json;

let notes;
try {
  const raw = claudeResponse.content[0].text;
  notes = JSON.parse(raw);
} catch (e) {
  throw new Error('Claude response was not valid JSON: ' + e.message);
}

const allowedClients = ['Nemours','AdventHealth','Paraveda','Sustena','CareMedx','ATAC','Encore','Internal'];
const allowedTypes = ['client','internal','1-1','workshop'];

const client = allowedClients.includes(notes.suggested_client) ? notes.suggested_client : null;
const meetingType = allowedTypes.includes(notes.suggested_meeting_type) ? notes.suggested_meeting_type : 'internal';
const attendees = Array.isArray(notes.attendees) ? notes.attendees : [];

const today = new Date().toISOString().slice(0, 10);

const yamlStr = (s) => JSON.stringify(String(s));
const yamlArr = (arr) => '[' + arr.map(yamlStr).join(', ') + ']';

const tags = ['meeting', 'otter-import'];
if (client) tags.push(client.toLowerCase());

const frontmatter = [
  '---',
  'type: meeting',
  `tags: ${yamlArr(tags)}`,
  `meeting_date: ${item.date}`,
  `meeting_type: ${meetingType}`,
  `client: ${client ? yamlStr(client) : 'null'}`,
  `attendees: ${yamlArr(attendees)}`,
  'promoted: false',
  `created: ${today}`,
  `updated: ${today}`,
  '---',
  ''
].join('\n');

const section = (title, lines) => lines.length
  ? `## ${title}\n\n` + lines.map(l => `- ${l}`).join('\n') + '\n\n'
  : '';

const body = [
  `# ${item.title}`,
  '',
  `**Source:** [Otter recording](${item.recording_url})  `,
  `**Duration:** ${Math.round(item.duration_seconds / 60)} min`,
  '',
  '## TL;DR',
  '',
  notes.tldr || '',
  '',
  section('Key Points', notes.key_points || []),
  section('Decisions', notes.decisions || []),
  section('Action Items', (notes.action_items || []).map(a => `[ ] ${a}`)),
  section('Open Questions', notes.open_questions || [])
].join('\n');

const noteMarkdown = frontmatter + '\n' + body;

const safeTitle = item.title.replace(/[\\/:*?"<>|]/g, '').trim();
const filePath = `${item.vaultInboxPath}/${item.date} ${safeTitle}.md`;

const notionCreateBody = {
  parent: { type: 'data_source_id', data_source_id: item.notionDataSourceId },
  properties: {
    Name: { title: [ { text: { content: item.title } } ] },
    Type: { select: { name: 'Meeting' } },
    'Note Date': { date: { start: item.date } },
    URL: { url: item.recording_url },
    'Duration (Seconds)': { number: item.duration_seconds }
  }
};

const notionQueryBody = {
  filter: { property: 'URL', url: { equals: item.recording_url } }
};

const blockParagraph = (text) => ({
  object: 'block',
  type: 'paragraph',
  paragraph: { rich_text: [ { type: 'text', text: { content: String(text).slice(0, 2000) } } ] }
});

const notionBlocksBody = {
  children: [
    blockParagraph(`TL;DR: ${notes.tldr || ''}`),
    ...(notes.key_points || []).map(p => blockParagraph(`Key point: ${p}`)),
    ...(notes.decisions || []).map(p => blockParagraph(`Decision: ${p}`)),
    ...(notes.action_items || []).map(p => blockParagraph(`Action item: ${p}`)),
    ...(notes.open_questions || []).map(p => blockParagraph(`Open question: ${p}`))
  ].slice(0, 100)
};

return {
  json: {
    ...item,
    notes,
    noteMarkdown,
    filePath,
    notionCreateBody,
    notionQueryBody,
    notionBlocksBody
  }
};

const data = $('Parse Synthesis + Build Payloads').item.json;
const buffer = Buffer.from(data.noteMarkdown, 'utf-8');
const binary = await this.helpers.prepareBinaryData(buffer, data.filePath.split('/').pop());

return {
  json: { filePath: data.filePath },
  binary: { data: binary }
};
